  let total = 0;
  let count = 0;
  for (const row of sales) {
    if (row.date >= start_date && row.date <= end_date) {
      total += row.amount;
      count += 1;
    }
  }
  return {
    content: [{ type: 'text', text: `Total amount: ${total}\nRow count: ${count}` }]
  };
